const L = (s: string) => RU[s] ?? s
const placement = (p: string) => {
  const m = p.match(/^(\d+)(?:st|nd|rd|th)(?:–(\d+)(?:st|nd|rd|th))?$/)
  return m ? (m[2] ? `${m[1]}–${m[2]} место` : `${m[1]}-е место`) : p
}
const stage = (s: string): string => {
  const round = s.match(/^Round of (\d+)$/)
  if (round) return `1/${Number(round[1]) / 2} финала`
  const losers = s.match(/^Losers Round (\d+)$/)
  if (losers) return `Нижняя сетка, раунд ${losers[1]}`
  return L(s)
}
const CAUSES: Record<string, string> = {
  "jumps they couldn't hit": 'непопадания в прыжки',
  "tapping they couldn't keep up with": 'не успевали по тэппингу',
  "patterns they couldn't read": 'непрочитанные паттерны',
  'running out of stamina': 'кончилась выносливость',
  nerves: 'нервы',
  'sloppy timing': 'неточный тайминг',
}
const failContext = (c: string) =>
  c
    .replace(/^ in a jump section$/, ' на прыжках')
    .replace(/^ at AR([\d.]+) with Hidden$/, ' на AR$1 с Hidden')
    .replace(/^ at AR([\d.]+)$/, ' на AR$1')
    .replace(/^: the hands gave out$/, ': руки не выдержали')
    .replace(/^ after losing composure$/, ' после потери самообладания')
    .replace(/^: timing fell apart$/, ': тайминг развалился')
    .replace(/^ during a (\d+) BPM stream \((\d+) notes\)$/, ' на стриме $1 BPM ($2 нот)')
    .replace(/^ in a fast tapping section$/, ' на быстром тэппинге')
const drill = (spaced: string) => L(DRILL_LABELS[spaced.replace(/ /g, '_')] ?? spaced)
const preset = (key: string) => L(PRESET_LABELS[key] ?? key)

type Out = string | ((...groups: string[]) => string)

export const RU_PATTERNS: [RegExp, Out][] = [
  // simulation & life events
  [/^(.+) reached (\d+)\.$/, (g, v) => `${L(g)}: достигнут уровень ${v}.`],
  [/^Something clicked: (.+) \+([\d.]+)\.$/, (s, j) => `Что-то щёлкнуло: ${L(s)} +${j}.`],
  [/^Severe tendonitis: forced (\d+)-day hiatus\. Without physiotherapy the stamina ceiling drops for good\.$/,
    'Тяжёлый тендинит: вынужденный перерыв на $1 дн. Без физиотерапии потолок выносливости упадёт навсегда.'],
  [/^(.+) is getting rusty \(up to -([\d.]+)\)\.$/, (g, v) => `${L(g)}: навык ржавеет (до −${v}).`],
  [/^Sponsorship deal pays \$([\d,]+) this month\.$/, 'Спонсорский контракт: $$1 в этом месяце.'],
  [/^Streaming sponsor pays \$([\d,]+) this month\.$/, 'Спонсор стримов: $$1 в этом месяце.'],
  [/^Stayed up late: ([\d.]+)h of sleep lost\.$/, 'Засиделись допоздна: недосып $1 ч.'],
  [/^Happy birthday! You're (\d+) now\.$/, 'С днём рождения! Вам $1.'],
  [/^Natural (.+)$/, (g) => `Талант: ${L(g.charAt(0).toUpperCase() + g.slice(1)).toLowerCase()}`],
  [/^Struggles with (.+)$/, (g) => `Слабое место: ${L(g.charAt(0).toUpperCase() + g.slice(1)).toLowerCase()}`],
  [/^Streamed ([\d.]+)h to ~(\d+) viewers: \+(\d+) followers, \$([\d,.]+)\.$/,
    'Стрим $1 ч, ~$2 зрителей: +$3 подписчиков, $$4.'],
  [/^New top play live on stream: (.+)$/, 'Новый топ-скор прямо на стриме: $1'],
  // map key moments
  [/^Failed at (.+?) \((\d+)%\)(.*)\.$/, (when, pct, ctx) => `Фейл на ${when} (${pct}%)${failContext(ctx)}.`],
  [/^Choked at (\d+)x with (\d+) notes left \((.+)\)\.$/, 'Чоук на $1x, до конца оставалось $2 нот ($3).'],
  [/^(\d+) of (\d+) misses came from (.+)\.$/, (a, b, c) => `${a} из ${b} миссов: ${CAUSES[c] ?? c}.`],
  // world news
  [/^(.+) \[(\w+)\] breaks into the global top (\d+)!$/, '$1 [$2] врывается в мировой топ-$3!'],
  [/^(.+) \[(\w+)\] is the new global #1!$/, '$1 [$2] — новый топ-1 мира!'],
  [/^pp system change: (.+?)\. (.+) Your total went from ([\d.]+)pp to ([\d.]+)pp\.$/,
    (n, s, a, b) => `Смена системы pp: ${L(n)}. ${L(s)} Ваши pp: ${a} → ${b}.`],
  [/^(.+) sniped your #1 on (.+)\.$/, '$1 перебивает ваш #1 на $2.'],
  [/^(.+) is out with a wrist injury \(~(\d+) weeks\)\.$/, '$1 выбывает с травмой запястья (~$2 нед.).'],
  [/^(.+) announces a break from osu! \(~(\d+) weeks\)\.$/, '$1 берёт перерыв от osu! (~$2 нед.).'],
  [/^(.+) retires from competitive osu!\.$/, '$1 завершает соревновательную карьеру.'],
  [/^(.+) goes quiet; the account has gone inactive\.$/, '$1 пропадает: аккаунт неактивен.'],
  [/^(.+) quietly retires\.$/, '$1 тихо уходит из игры.'],
  [/^(.+) is back!$/, '$1 возвращается!'],
  // tournaments
  [/^You've been selected for Team (\w+) at (.+)!$/, 'Вас выбрали в сборную $1 на $2!'],
  [/^(.+) qualifiers: you placed #(\d+) of (\d+)\.$/, 'Квалификация $1: вы на $2-м месте из $3.'],
  [/^(.+): the week (\d+) pool is out\.$/, '$1: опубликован маппул недели $2.'],
  [/^Prize money from (.+): \$([\d,.]+) \((.+)\)\.$/, (t, a, p) => `Призовые с ${t}: $${a} (${placement(p)}).`],
  [/^You won (.+)!$/, 'Вы выиграли $1!'],
  [/^You finished 2nd at (.+)\.$/, 'Второе место на $1.'],
  [/^Eliminated from (.+): (.+)\.$/, (t, p) => `Вылет с ${t}: ${placement(p)}.`],
  [/^You forfeited your (.+) match at (.+): (.+)\.$/, (s, t, r) => `Техническое поражение: ${stage(s)}, ${t} (${L(r)}).`],
  [/^~(\d+) watched your (.+) match: \+(\d+) followers\.$/, (v, s, f) => `~${v} зрителей смотрели ваш матч (${stage(s)}): +${f} подписчиков.`],
  [/^Upset at (.+): (.+) \(seed (\d+)\) beats (.+) \(seed (\d+)\) (\d+-\d+) in (.+)\.$/,
    (t, a, sa, b, sb, sc, s) => `Сенсация на ${t}: ${a} (посев ${sa}) обыгрывает ${b} (посев ${sb}) ${sc}, ${stage(s)}.`],
  [/^(.+) wins (.+)\.$/, '$1 выигрывает $2.'],
  [/^(Round of \d+|Losers Round \d+)$/, (s) => stage(s)],
  [/^(\d+(?:st|nd|rd|th)(?:–\d+(?:st|nd|rd|th))?)$/, (p) => placement(p)],
  // week summaries
  [/^rest \+ physio$/, 'отдых + физиотерапия'],
  [/^rest$/, 'отдых'],
  [/^([a-z0-9_ ]+?) ([\d.]+)h, (\d+)\/(\d+) passed$/, (k, h, a, b) => `${preset(k)} ${h} ч, пройдено ${a}/${b}`],
  [/^([a-z0-9 ]+?) ([\d.]+)h$/, (k, h) => `${drill(k)} ${h} ч`],
  [/^tournament match on (.+): play it first$/, 'турнирный матч $1: сначала сыграйте его'],
  // errors
  [/^on (.+) you only have ([\d.]+)h of free time \(max ([\d.]+)h if you skip sleep\)$/,
    '$1 у вас всего $2 ч свободного времени (максимум $3 ч, если жертвовать сном)'],
  [/^recovering from severe RSI until (.+)$/, 'восстановление после тяжёлой травмы до $1'],
  [/^(.+) doesn't exist yet in (\d+)$/, (d, y) => `«${L(d)}» ещё не существует в ${y} году`],
  [/^(.+) isn't a thing yet in (\d+)$/, (d, y) => `«${L(d)}» ещё не существует в ${y} году`],
  [/^(.+) isn't out yet in (\d+)$/, '$1 ещё не вышел в $2 году'],
  [/^(.+) is no longer sold$/, '$1 больше не продаётся'],
  [/^you already own (.+)$/, '$1 у вас уже есть'],
  [/^(.+) costs \$(\d+); you have \$(-?\d+)$/, '$1 стоит $$2, а у вас $$3'],
  [/^(\d+) days of physiotherapy cost \$(\d+); you have \$(-?\d+)$/, '$1 дн. физиотерапии стоят $$2, а у вас $$3'],
  [/^buy a (mouse|tablet) first$/, (d) => (d === 'mouse' ? 'сначала купите мышь' : 'сначала купите планшет')],
  [/^that's ([\d.]+)h of playing; the limit is (\d+)h a day$/, 'это $1 ч игры, а лимит — $2 ч в день'],
  [/^that's (\d+) 1v1s today already; your hands need a break$/, 'сегодня уже $1 дуэли, рукам нужен отдых'],
  [/^(.+) declined: they don't usually play 1v1s with someone (\d+)x lower ranked$/,
    '$1 отказывается: обычно не играет 1v1 с теми, кто в $2 раз ниже по рангу'],
  [/^(.+) isn't your rival \(yet\)$/, '$1 вам (пока) не соперник'],
  [/^(.+) isn't available \((\w+)\)$/, (n, s) => `${n} сейчас недоступен (${L(s === 'hiatus' ? 'on hiatus' : s)})`],
  [/^this 1v1 is (expired|played)$/, (s) => (s === 'expired' ? 'вызов сгорел' : 'эта дуэль уже сыграна')],
  [/^registration opens on (.+)$/, 'регистрация откроется $1'],
  [/^(BWS rank|rank) #(\d+) is outside (.+)$/, (k, r, range) => `${k === 'rank' ? 'ранг' : 'BWS-ранг'} #${r} вне диапазона ${range}`],
  [/^this match is scheduled for (.+)$/, 'матч назначен на $1'],
  [/^no player called (.+) in this world$/, 'в этом мире нет игрока $1'],
  [/^format must be one of (.+)$/, 'формат: $1'],
]

